/* HEXA BATTLEGROUNDS setup — PART 25 OF 28. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pic-0', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🪜 + 👨","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🧈 + 🪰","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🍯 + 🌙","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["STEPFATHER"]},{"label":"Picture 2 (Decoder)","accept":["BUTTERFLY"]},{"label":"Picture 3 (Intel)","accept":["HONEYMOON"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER.', 'STEPFATHER: step + father | BUTTERFLY: butter + fly | HONEYMOON: honey + moon', null, 25, 'published'), ('mission-pic-1', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"💡 + 🏠","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🔥 + 🧱","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🔥 + 🦊","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["LIGHTHOUSE"]},{"label":"Picture 2 (Decoder)","accept":["FIREWALL"]},{"label":"Picture 3 (Intel)","accept":["FIREFOX"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER.', 'LIGHTHOUSE: light + house | FIREWALL: fire + wall | FIREFOX: fire + fox', null, 25, 'published'), ('mission-pic-2', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🌧️ + 🎀","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🦶 + ⚽","mono":false,"big":true},"intel":{"title":"Picture 3","body":"⭐ + 🐟","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["RAINBOW"]},{"label":"Picture 2 (Decoder)","accept":["FOOTBALL"]},{"label":"Picture 3 (Intel)","accept":["STARFISH"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER.', 'RAINBOW: rain + bow | FOOTBALL: foot + ball | STARFISH: star + fish', null, 25, 'published'), ('mission-pic-3', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🥚 + 🍆","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🐎 + 👞","mono":false,"big":true},"intel":{"title":"Picture 3","body":"✋ + 👜","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["EGGPLANT"]},{"label":"Picture 2 (Decoder)","accept":["HORSESHOE"]},{"label":"Picture 3 (Intel)","accept":["HANDBAG"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER.', 'EGGPLANT: egg + plant | HORSESHOE: horse + shoe | HANDBAG: hand + bag', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pic-4', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🦷 + 🖌️","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🛏️ + 🪨","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🧠 + ⛈️","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["TOOTHBRUSH"]},{"label":"Picture 2 (Decoder)","accept":["BEDROCK"]},{"label":"Picture 3 (Intel)","accept":["BRAINSTORM"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER.', 'TOOTHBRUSH: tooth + brush | BEDROCK: bed + rock | BRAINSTORM: brain + storm', null, 25, 'published'), ('recovery-pic-0', 'picture', 'recovery', 'Picture Riddles', 'picture', 1, array['any']::text[], 'Get back on your feet: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"☀️ + 🌻","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🔑 + 🎹","mono":false,"big":true},"intel":{"title":"Picture 3","body":"☁️ + 🖥️","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["SUNFLOWER"]},{"label":"Picture 2 (Decoder)","accept":["KEYBOARD"]},{"label":"Picture 3 (Intel)","accept":["CLOUDCOMPUTING","CLOUDCOMPUTER"]}]'::jsonb, false, 5, 120, 'Say the emoji out loud and join the words.', 'SUNFLOWER: sun + flower | KEYBOARD: key + board | CLOUD COMPUTING: cloud + computer → cloud computing', null, 25, 'published'), ('recovery-pic-1', 'picture', 'recovery', 'Picture Riddles', 'picture', 1, array['any']::text[], 'Get back on your feet: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🐝 + 🍃","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🌊 + 🐎","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🕷️ + 🕸️ + 🌐","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["BAYLEAF","BEELEAF"]},{"label":"Picture 2 (Decoder)","accept":["SEAHORSE"]},{"label":"Picture 3 (Intel)","accept":["WORLDWIDEWEB","WEBSITE","WWW"]}]'::jsonb, false, 5, 120, 'Say the emoji out loud and join the words.', 'BAYLEAF: bee (bay) + leaf | SEAHORSE: sea + horse | WORLD WIDE WEB: the world-wide web', null, 25, 'published'), ('mission-riddle-0', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I have keys but open no locks. I have space but no room. You can enter, but you can''t go inside.","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"The more you take, the more you leave behind.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What has to be broken before you can use it?","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["KEYBOARD"]},{"label":"Riddle 2 (Decoder)","accept":["FOOTSTEPS","FOOTSTEP","STEPS"]},{"label":"Riddle 3 (Intel)","accept":["EGG","ANEGG"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'KEYBOARD: a keyboard | FOOTSTEPS: footsteps | EGG: an egg', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-riddle-1', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I''m tall when I''m young and short when I''m old.","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"I have a neck but no head, and I wear a cap.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"I have many teeth but I can''t bite.","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["CANDLE","ACANDLE"]},{"label":"Riddle 2 (Decoder)","accept":["BOTTLE","ABOTTLE"]},{"label":"Riddle 3 (Intel)","accept":["COMB","ACOMB","ZIP","ZIPPER"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'CANDLE: a candle | BOTTLE: a bottle | COMB: a comb', null, 25, 'published'), ('mission-riddle-2', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"What gets wetter the more it dries?","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"I have cities but no houses, forests but no trees, water but no fish.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What can you catch but never throw?","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["TOWEL","ATOWEL"]},{"label":"Riddle 2 (Decoder)","accept":["MAP","AMAP"]},{"label":"Riddle 3 (Intel)","accept":["COLD","ACOLD"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'TOWEL: a towel | MAP: a map | COLD: a cold', null, 25, 'published'), ('mission-riddle-3', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I have one eye but cannot see.","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"I speak without a mouth and hear without ears.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What goes up but never comes down?","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["NEEDLE","ANEEDLE"]},{"label":"Riddle 2 (Decoder)","accept":["ECHO","ANECHO"]},{"label":"Riddle 3 (Intel)","accept":["AGE","YOURAGE"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'NEEDLE: a needle | ECHO: an echo | AGE: your age', null, 25, 'published'), ('mission-riddle-4', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I have a head and a tail but no body.","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"The more of me there is, the less you see.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What has hands but can''t clap?","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["COIN","ACOIN"]},{"label":"Riddle 2 (Decoder)","accept":["DARKNESS","DARK","FOG"]},{"label":"Riddle 3 (Intel)","accept":["CLOCK","ACLOCK","WATCH"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'COIN: a coin | DARKNESS: darkness | CLOCK: a clock', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-movie-0', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🚢 🧊 💔","mono":false,"big":true},"decoder":{"title":"Film 2","body":"🦁 👑","mono":false,"big":true},"intel":{"title":"Film 3","body":"🦖 🏞️ 🚙","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["TITANIC"]},{"label":"Film 2 (Decoder)","accept":["THELIONKING","LIONKING"]},{"label":"Film 3 (Intel)","accept":["JURASSICPARK","JURASSICWORLD"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional.', 'TITANIC: ship, iceberg, heartbreak | THE LION KING: lion + crown | JURASSIC PARK: dinosaur park', null, 25, 'published'), ('mission-movie-1', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🥋 🐼","mono":false,"big":true},"decoder":{"title":"Film 2","body":"❄️ 👸 ⛄","mono":false,"big":true},"intel":{"title":"Film 3","body":"🕷️ 👨 🏙️","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["KUNGFUPANDA"]},{"label":"Film 2 (Decoder)","accept":["FROZEN"]},{"label":"Film 3 (Intel)","accept":["SPIDERMAN"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional.', 'KUNG FU PANDA: kung fu + panda | FROZEN: ice queen + snowman | SPIDERMAN: spider + man', null, 25, 'published'), ('mission-movie-2', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🔍 🐠","mono":false,"big":true},"decoder":{"title":"Film 2","body":"🧸 📖","mono":false,"big":true},"intel":{"title":"Film 3","body":"3️⃣ 🤪 🎓","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["FINDINGNEMO","NEMO"]},{"label":"Film 2 (Decoder)","accept":["TOYSTORY"]},{"label":"Film 3 (Intel)","accept":["3IDIOTS","THREEIDIOTS"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional.', 'FINDING NEMO: finding + fish | TOY STORY: toy + story | 3 IDIOTS: three idiots at college', null, 25, 'published'), ('mission-movie-3', 'movie', 'mission', 'Emoji Cinema', 'movies', 1, array['any','social','food','costa','sports','public']::text[], 'Each teammate holds a movie told in emoji. Name all three films.', '{"scout":{"title":"Film 1","body":"🤼‍♀️ 👨‍👧‍👧 🥇","mono":false,"big":true},"decoder":{"title":"Film 2","body":"⚡ 🧙‍♂️ 👓","mono":false,"big":true},"intel":{"title":"Film 3","body":"🦈 🌊 🏊","mono":false,"big":true}}'::jsonb, '[{"label":"Film 1 (Scout)","accept":["DANGAL"]},{"label":"Film 2 (Decoder)","accept":["HARRYPOTTER"]},{"label":"Film 3 (Intel)","accept":["JAWS"]}]'::jsonb, false, 3, 200, 'Mix of Hollywood and Indian blockbusters. Spelling of "The" is optional.', 'DANGAL: wrestling father and daughters | HARRY POTTER: scar, wizard, glasses | JAWS: shark attack', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
